<template><view class="page"><view class="title">文献知识卡片</view><button class="primary" @tap="show=!show">＋ 新增并分析</button><view v-if="show" class="card form"><input v-model="form.title" placeholder="文献标题"/><textarea v-model="form.abstract_excerpt" placeholder="摘要摘抄（必填其一）"/><textarea v-model="form.note" placeholder="个人笔记（必填其一）"/><textarea v-model="form.research_gap" placeholder="你识别的研究缺口（可选）"/><textarea v-model="form.reference_idea" placeholder="借鉴思路（可选）"/><button @tap="preview">先预览AI整理</button><button class="primary" @tap="save">确认保存</button></view><view v-if="analysis" class="card preview"><view class="label">临时分析预览（尚未保存）</view><view>总结：{{analysis.summary}}</view><view>研究问题：{{analysis.research_problem}}</view><view>方法：{{analysis.method}}</view><view>创新点：{{analysis.innovation}}</view><view>局限：{{analysis.limitation}}</view><view>课题关联：{{analysis.relation}}</view></view><view v-for="n in notes" :key="n.id" class="card"><view class="paper">{{n.title}}</view><view class="label">AI总结</view><view>{{n.summary||n.abstract_excerpt}}</view><view class="label">创新点 / 局限</view><view>{{n.innovation||'待补充'}} / {{n.research_gap||'待补充'}}</view><view class="label">与课题关系</view><view>{{n.relation||n.reference_idea}}</view></view></view></template>
<script setup>import{reactive,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../utils/api';const notes=ref([]),show=ref(false),analysis=ref(null),form=reactive({title:'',abstract_excerpt:'',note:'',research_gap:'',reference_idea:''});async function load(){notes.value=await api.notes()}function valid(){if(!form.title.trim()||(!form.abstract_excerpt.trim()&&!form.note.trim())){uni.showToast({title:'请填写标题及摘要/笔记',icon:'none'});return false}return true}async function preview(){if(!valid())return;try{analysis.value=(await api.previewNote({...form})).analysis}catch(e){uni.showToast({title:'无法分析',icon:'none'})}}async function save(){if(!valid())return;try{await api.addNote({...form});Object.keys(form).forEach(k=>form[k]='');analysis.value=null;show.value=false;load()}catch(e){uni.showModal({title:'无法保存',content:e.detail?.message||'可能存在重复文献或未激活课题',showCancel:false})}}onShow(load)</script>
<style scoped>button{margin-bottom:20rpx}.paper{font-weight:700;font-size:30rpx}.label{color:#3068e8;font-size:24rpx;margin:16rpx 0 6rpx}.form textarea{height:130rpx}.preview{border:2rpx dashed #7898e8}.preview view{margin-bottom:10rpx}</style>
